import clsx from 'clsx';
import React, { useLayoutEffect } from 'react';

import { divPlotLayout } from '../../../../core/components/chart-grid/ChartGridRoot.sty.js';
import { useSetResetOverlaysState } from '../../../hooks/store/state-setters.js';
import { useHistogramTooltip } from '../../../hooks/useHistogramTooltip.js';
import { HistogramDatapoints } from '../HistogramDatapoints.js';
import { inspectDatapointsLayout } from '../HistogramOverlays.sty.js';
import { HistogramTooltip } from '../HistogramTooltip.js';
import { useClosestBinsByMouse } from '../hooks/useClosestBinsByMouse.js';
import { usePinnedAwarePosition } from '../hooks/usePinnedAwarePosition.js';

export function HistogramInspect() {
  const mousePosition = usePinnedAwarePosition();

  const { variant } = useHistogramTooltip();
  const setResetOverlaysState = useSetResetOverlaysState();
  const { closestBin, closestBins, closestGroupedBins } =
    useClosestBinsByMouse(mousePosition);

  useLayoutEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setResetOverlaysState();
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  const closestBinsByVariant =
    variant === 'grouped'
      ? closestGroupedBins.find((innerArray) =>
          innerArray.some((item) => item.id === closestBin?.id),
        )
      : closestBins;

  return mousePosition ? (
    <>
      <div className={clsx(divPlotLayout, inspectDatapointsLayout)}>
        <HistogramDatapoints
          closestPoint={closestBin}
          groupedPoints={closestGroupedBins}
        />
      </div>
      <HistogramTooltip
        points={closestBinsByVariant}
        closestPoint={closestBin}
      />
    </>
  ) : null;
}
